from __future__ import annotations

import sys
from typing import Any, Dict, List

from .models import Line


class TableRenderer:
    """Columnar table renderer with optional TSV mode.

    Args:
        tsv: If True, output tab-separated values instead of formatted columns.
    """

    def __init__(self, tsv: bool = False) -> None:
        self.tsv = tsv

    def render(self, lines: List[Line]) -> str:
        if not lines:
            return "no results"

        # Collect all keys preserving order; skip internal fields starting with _
        keys: List[str] = []
        seen: set = set()
        for line in lines:
            for k in line.keys():
                if k not in seen and not k.startswith("_"):
                    keys.append(k)
                    seen.add(k)

        if self.tsv:
            header = "\t".join(keys)
            rows = []
            for line in lines:
                row = "\t".join(str(line.get(k, "")) for k in keys)
                rows.append(row)
            return header + "\n" + "\n".join(rows)

        # Calculate column widths (max 80 chars per cell)
        col_widths: Dict[str, int] = {}
        for key in keys:
            max_w = len(key)
            for line in lines:
                val_str = str(line.get(key, ""))
                if len(val_str) > 80:
                    val_str = val_str[:77] + "..."
                max_w = max(max_w, len(val_str))
            col_widths[key] = min(max_w, 80)

        # Build header row
        header_parts = [key.ljust(col_widths[key]) for key in keys]
        header = " | ".join(header_parts)
        separator = "-+-".join("-" * col_widths[k] for k in keys)

        # Build data rows
        rows = []
        for line in lines:
            row_parts = []
            for key in keys:
                val_str = str(line.get(key, ""))
                if len(val_str) > 80:
                    val_str = val_str[:77] + "..."
                row_parts.append(val_str.ljust(col_widths[key]))
            rows.append(" | ".join(row_parts))

        return header + "\n" + separator + "\n" + "\n".join(rows)


class BarsRenderer:
    """Horizontal ASCII bar chart renderer.

    Displays key, value, and a proportional bar (max width 40 chars).
    Long keys are truncated to 30 characters with ellipsis.

    Args:
        key_field: Field name for the label.
        value_field: Field name for the numeric value.
    """

    def __init__(
        self, key_field: str = "key", value_field: str = "value"
    ) -> None:
        self.key_field = key_field
        self.value_field = value_field

    @staticmethod
    def _to_float(v: Any) -> float:
        try:
            return float(v)
        except (ValueError, TypeError):
            return 0.0

    def render(self, lines: List[Line]) -> str:
        if not lines:
            return "no results"

        # Find max value for scaling
        max_val = 0.0
        for line in lines:
            v = self._to_float(line.get(self.value_field, 0))
            if v > max_val:
                max_val = v

        bar_width = 40
        output_lines: List[str] = []

        for line in lines:
            key_str = str(line.get(self.key_field, ""))
            # Truncate long keys to 30 chars (27 + ellipsis)
            if len(key_str) > 30:
                key_str = key_str[:27] + "..."

            v = self._to_float(line.get(self.value_field, 0))

            if max_val > 0:
                bar_len = int((v / max_val) * bar_width)
            else:
                bar_len = 0

            bar = "\u2588" * bar_len
            output_lines.append(f"{key_str:<30} | {bar} ({v})")

        return "\n".join(output_lines)
